import { formatPersonName } from "@jcoder/abp-react/i18n";
import { useCulture, useLocalization, usePermissionChecker } from "@jcoder/abp-react/react";
import { createFileRoute } from "@tanstack/react-router";
import { KeyRound } from "lucide-react";
import { lazy, Suspense, useCallback, useMemo, useState } from "react";
import { toast } from "sonner";
import { z } from "zod";
import {
  getApiIdentityUsersIdRoles,
  getGetApiIdentityUsersQueryKey,
  useDeleteApiIdentityUsersId,
  useGetApiIdentityUsers,
  useGetApiIdentityUsersAssignableRoles,
  usePostApiIdentityUsers,
  usePutApiIdentityUsersId,
} from "@/api/endpoints/user/user";
import type {
  VoloAbpIdentityIdentityUserCreateDto,
  VoloAbpIdentityIdentityUserDto,
  VoloAbpIdentityIdentityUserUpdateDto,
} from "@/api/models";
import { requirePermission } from "@/auth";
import { createCrudService } from "@/components/abp/crud/crud-service";
import { useAbpSheet } from "@/components/abp/sheet/use-abp-sheet";
import { StatusBadge } from "@/components/abp/table/status-badge";
import { useAbpTable } from "@/components/abp/table/use-abp-table";
import type { ComboboxOption } from "@/components/combobox/use-combobox-options";
import type { TableColumnDef } from "@/components/data-table/table-core";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";
import { IdentityPermissions } from "@/permissions";
import { RouteError } from "@/routes/shell-boundary";

// 编辑/权限面板的重依赖（combobox、tree、accordion 等）按需加载：列表首屏不背这批模块。
const PermissionSheet = lazy(() =>
  import("@/components/abp/permission/permission-sheet").then((m) => ({
    default: m.PermissionSheet,
  })),
);

/** 用户 DTO 不带 roleNames，故 open() 需先 GET .../roles 再开 sheet。 */
export const Route = createFileRoute("/_layout/_authed/identity/users")({
  beforeLoad: requirePermission(IdentityPermissions.Users.Default),
  errorComponent: RouteError,
  component: UsersPage,
});

const userService = createCrudService({
  useList: useGetApiIdentityUsers,
  useCreate: usePostApiIdentityUsers,
  useUpdate: usePutApiIdentityUsersId,
  useDelete: useDeleteApiIdentityUsersId,
  listKey: getGetApiIdentityUsersQueryKey,
  policy: IdentityPermissions.Users.Default,
});

interface UserFormValues {
  userName: string;
  email: string;
  name: string;
  surname: string;
  phoneNumber: string;
  password: string;
  isActive: boolean;
  roleNames: string[];
}

const EMPTY_VALUES: UserFormValues = {
  userName: "",
  email: "",
  name: "",
  surname: "",
  phoneNumber: "",
  password: "",
  isActive: true,
  roleNames: [],
};

/** 不能走默认 pick：roleNames 来自异步预取、password 必须回空（不回显）。 */
function toRecordValues(
  record: VoloAbpIdentityIdentityUserDto,
  roleNames: string[],
): UserFormValues {
  return {
    userName: record.userName ?? "",
    email: record.email ?? "",
    name: record.name ?? "",
    surname: record.surname ?? "",
    phoneNumber: record.phoneNumber ?? "",
    password: "",
    isActive: record.isActive ?? true,
    roleNames,
  };
}

/** 不能走默认 identity：可选字段空串归一为 undefined（不给后端发 `name: ""`）。 */
function toCreateInput(value: UserFormValues): VoloAbpIdentityIdentityUserCreateDto {
  return {
    userName: value.userName,
    email: value.email,
    name: value.name || undefined,
    surname: value.surname || undefined,
    phoneNumber: value.phoneNumber || undefined,
    password: value.password,
    isActive: value.isActive,
    roleNames: value.roleNames,
  };
}

/** 不能走默认 identity：edit 不渲染 password 字段（留空=不改）；value.password 恒为初始空串，
 *  故 update body 里永远不带 password，后端保持原密码不变；其余可选字段同 toCreateInput，
 *  空串归一为 undefined（不给后端发 `name: ""`）。 */
function toUpdateInput(value: UserFormValues): VoloAbpIdentityIdentityUserUpdateDto {
  return {
    userName: value.userName,
    email: value.email,
    name: value.name || undefined,
    surname: value.surname || undefined,
    phoneNumber: value.phoneNumber || undefined,
    isActive: value.isActive,
    roleNames: value.roleNames,
  };
}

function UsersPage() {
  const L = useLocalization();
  const culture = useCulture();
  const can = usePermissionChecker();
  const canManagePermissions = can(IdentityPermissions.Users.ManagePermissions);
  const [permissionsFor, setPermissionsFor] = useState<VoloAbpIdentityIdentityUserDto | null>(null);

  // 引用必须稳定：进 AbpTable 的 columns memo 依赖，内联箭头会让列模型每渲染重建（DEV 有 churn 告警）。
  const permissionMenuItem = useCallback(
    (row: VoloAbpIdentityIdentityUserDto) =>
      canManagePermissions ? (
        <DropdownMenuItem onSelect={() => setPermissionsFor(row)}>
          <KeyRound />
          {L("Admin:Permissions")}
        </DropdownMenuItem>
      ) : null,
    [canManagePermissions, L],
  );

  const columns = useMemo<TableColumnDef<VoloAbpIdentityIdentityUserDto>[]>(
    () => [
      { accessorKey: "userName", header: () => L("AbpIdentity::UserName") },
      {
        id: "fullName",
        header: () => L("Admin:FullName"),
        enableSorting: false,
        cell: ({ row }) =>
          formatPersonName({ name: row.original.name, surname: row.original.surname, culture }),
      },
      { accessorKey: "email", header: () => L("AbpIdentity::DisplayName:Email") },
      {
        accessorKey: "isActive",
        header: () => L("AbpIdentity::DisplayName:IsActive"),
        enableSorting: false,
        cell: ({ getValue }) => (
          <StatusBadge status={getValue() ? "success" : "neutral"}>
            {getValue() ? L("Admin:Yes") : L("Admin:No")}
          </StatusBadge>
        ),
      },
    ],
    [L, culture],
  );

  const sheet = useAbpSheet(userService, {
    emptyValues: EMPTY_VALUES,
    // 用户 DTO 不带 roleNames，view/edit 打开前先取一次当前角色再开 sheet；AbpTable 的 onOpen
    // 是 fire-and-forget，GET 失败必须在这里兜住提示并取消打开，否则用户只看到点击无响应。
    toValues: async (record, mode) => {
      let roleNames: string[] = [];
      if (record.id && mode !== "create") {
        try {
          const roles = await getApiIdentityUsersIdRoles(record.id);
          roleNames = (roles.items ?? [])
            .map((role) => role.name ?? "")
            .filter((name) => name.length > 0);
        } catch {
          toast.error(L("Crud:OperationFailed"));
          return null;
        }
      }
      return toRecordValues(record, roleNames);
    },
    toCreate: toCreateInput,
    toUpdate: toUpdateInput,
    schema: (mode) => {
      const isCreate = mode === "create";
      return z.object({
        userName: z.string().trim().min(1, L("Form:Required")),
        email: z
          .string()
          .trim()
          .min(1, L("Form:Required"))
          .pipe(z.email(L("Form:InvalidEmail"))),
        name: z.string(),
        surname: z.string(),
        phoneNumber: z.string(),
        password: isCreate ? z.string().trim().min(1, L("Form:Required")) : z.string(),
        isActive: z.boolean(),
        roleNames: z.array(z.string()),
      });
    },
  });

  const t = useAbpTable(userService, {
    columns,
    row: { menu: permissionMenuItem },
    onOpen: sheet.open,
  });

  // MultiCombobox 的角色候选项只在编辑态（create/edit）且有 Update 权限时才拉，防止 view 态
  // 或无权限用户触发一次注定被后端 403 的请求。
  const assignableRolesQuery = useGetApiIdentityUsersAssignableRoles({
    query: { enabled: t.source.can.update && sheet.mode !== undefined && sheet.mode !== "view" },
  });
  const roleOptions: ComboboxOption[] = (assignableRolesQuery.data?.items ?? []).map((role) => ({
    value: role.name ?? "",
    label: role.name ?? "",
  }));

  const rolesEditable = t.source.can.update && sheet.mode !== "view";

  return (
    <section className="space-y-4">
      <h1 className="text-2xl font-normal">{L("AbpIdentity::Users")}</h1>
      <t.Table>
        <t.BulkBar>
          <t.BulkDelete />
        </t.BulkBar>
      </t.Table>
      <sheet.Sheet>
        <sheet.form.AppForm>
          <sheet.form.FormErrors />
        </sheet.form.AppForm>

        <sheet.form.AppField name="userName">
          {(field) => (
            <field.TextField
              label={L("AbpIdentity::UserName")}
              required
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="email">
          {(field) => (
            <field.TextField
              label={L("AbpIdentity::DisplayName:Email")}
              type="email"
              required
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="name">
          {(field) => (
            <field.TextField label={L("AbpIdentity::DisplayName:Name")} disabled={sheet.readOnly} />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="surname">
          {(field) => (
            <field.TextField label={L("AbpIdentity::Surname")} disabled={sheet.readOnly} />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="phoneNumber">
          {(field) => (
            <field.TextField label={L("AbpIdentity::PhoneNumber")} disabled={sheet.readOnly} />
          )}
        </sheet.form.AppField>

        {sheet.mode === "create" && (
          <sheet.form.AppField name="password">
            {(field) => (
              <field.TextField label={L("AbpIdentity::Password")} type="password" required />
            )}
          </sheet.form.AppField>
        )}

        <sheet.form.AppField name="isActive">
          {(field) => (
            <field.SwitchField
              label={L("AbpIdentity::DisplayName:IsActive")}
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="roleNames">
          {(field) => (
            <field.MultiComboboxField
              label={L("AbpIdentity::Roles")}
              options={roleOptions}
              editable={rolesEditable}
            />
          )}
        </sheet.form.AppField>
      </sheet.Sheet>
      {permissionsFor && (
        <Suspense fallback={null}>
          <PermissionSheet
            providerName="U"
            providerKey={permissionsFor.id ?? ""}
            open={permissionsFor !== null}
            onOpenChange={(open) => !open && setPermissionsFor(null)}
            title={`${L("Admin:Permissions")} · ${permissionsFor.userName ?? ""}`}
          />
        </Suspense>
      )}
    </section>
  );
}

import { useLocalization, usePermissionChecker } from "@jcoder/abp-react/react";
import { createFileRoute } from "@tanstack/react-router";
import { KeyRound } from "lucide-react";
import { lazy, Suspense, useCallback, useMemo, useState } from "react";
import {
  getGetApiIdentityRolesQueryKey,
  useDeleteApiIdentityRolesId,
  useGetApiIdentityRoles,
  usePostApiIdentityRoles,
  usePutApiIdentityRolesId,
} from "@/api/endpoints/role/role";
import type { VoloAbpIdentityIdentityRoleDto } from "@/api/models";
import { requirePermission } from "@/auth";
import { createCrudService } from "@/components/abp/crud/crud-service";
import { useAbpSheet } from "@/components/abp/sheet/use-abp-sheet";
import { StatusBadge } from "@/components/abp/table/status-badge";
import { useAbpTable } from "@/components/abp/table/use-abp-table";
import type { TableColumnDef } from "@/components/data-table/table-core";
import { DropdownMenuItem } from "@/components/ui/dropdown-menu";
import { IdentityPermissions } from "@/permissions";
import { buildRoleSchema } from "@/routes/_layout/_authed/identity/-role-schema";
import { RouteError } from "@/routes/shell-boundary";

// 权限面板的重依赖（tree、accordion 等）按需加载：列表首屏不背这批模块。
const PermissionSheet = lazy(() =>
  import("@/components/abp/permission/permission-sheet").then((m) => ({
    default: m.PermissionSheet,
  })),
);

/** 角色本身无可分配对象，故无角色 MultiCombobox。 */
export const Route = createFileRoute("/_layout/_authed/identity/roles")({
  beforeLoad: requirePermission(IdentityPermissions.Roles.Default),
  errorComponent: RouteError,
  component: RolesPage,
});

const roleService = createCrudService({
  useList: useGetApiIdentityRoles,
  useCreate: usePostApiIdentityRoles,
  useUpdate: usePutApiIdentityRolesId,
  useDelete: useDeleteApiIdentityRolesId,
  listKey: getGetApiIdentityRolesQueryKey,
  policy: IdentityPermissions.Roles.Default,
});

interface RoleFormValues {
  name: string;
  isDefault: boolean;
  isPublic: boolean;
}

const EMPTY_VALUES: RoleFormValues = { name: "", isDefault: false, isPublic: false };

function RolesPage() {
  const L = useLocalization();
  const can = usePermissionChecker();
  const canManagePermissions = can(IdentityPermissions.Roles.ManagePermissions);
  const [permissionsFor, setPermissionsFor] = useState<VoloAbpIdentityIdentityRoleDto | null>(null);

  const roleSchema = buildRoleSchema(L);

  // 引用必须稳定：进 AbpTable 的 columns memo 依赖，内联箭头会让列模型每渲染重建（DEV 有 churn 告警）。
  const permissionMenuItem = useCallback(
    (row: VoloAbpIdentityIdentityRoleDto) =>
      canManagePermissions ? (
        <DropdownMenuItem onSelect={() => setPermissionsFor(row)}>
          <KeyRound />
          {L("Admin:Permissions")}
        </DropdownMenuItem>
      ) : null,
    [canManagePermissions, L],
  );

  const columns = useMemo<TableColumnDef<VoloAbpIdentityIdentityRoleDto>[]>(
    () => [
      { accessorKey: "name", header: () => L("AbpIdentity::DisplayName:RoleName") },
      {
        accessorKey: "isDefault",
        header: () => L("AbpIdentity::DisplayName:IsDefault"),
        enableSorting: false,
        cell: ({ getValue }) => (
          <StatusBadge status={getValue() ? "info" : "neutral"}>
            {getValue() ? L("Admin:Yes") : L("Admin:No")}
          </StatusBadge>
        ),
      },
      {
        accessorKey: "isPublic",
        header: () => L("AbpIdentity::DisplayName:IsPublic"),
        enableSorting: false,
        cell: ({ getValue }) => (
          <StatusBadge status={getValue() ? "info" : "neutral"}>
            {getValue() ? L("Admin:Yes") : L("Admin:No")}
          </StatusBadge>
        ),
      },
    ],
    [L],
  );

  const sheet = useAbpSheet(roleService, {
    emptyValues: EMPTY_VALUES,
    schema: () => roleSchema,
  });

  const t = useAbpTable(roleService, {
    columns,
    row: { menu: permissionMenuItem },
    onOpen: sheet.open,
  });

  return (
    <section className="space-y-4">
      <h1 className="text-2xl font-normal">{L("AbpIdentity::Roles")}</h1>
      <t.Table>
        <t.BulkBar>
          <t.BulkDelete />
        </t.BulkBar>
      </t.Table>
      <sheet.Sheet>
        <sheet.form.AppForm>
          <sheet.form.FormErrors />
        </sheet.form.AppForm>

        <sheet.form.AppField name="name">
          {(field) => (
            <field.TextField
              label={L("AbpIdentity::DisplayName:RoleName")}
              required
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="isDefault">
          {(field) => (
            <field.SwitchField
              label={L("AbpIdentity::DisplayName:IsDefault")}
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>

        <sheet.form.AppField name="isPublic">
          {(field) => (
            <field.SwitchField
              label={L("AbpIdentity::DisplayName:IsPublic")}
              disabled={sheet.readOnly}
            />
          )}
        </sheet.form.AppField>
      </sheet.Sheet>
      {permissionsFor && (
        <Suspense fallback={null}>
          <PermissionSheet
            providerName="R"
            providerKey={permissionsFor.name ?? ""}
            open={permissionsFor !== null}
            onOpenChange={(open) => !open && setPermissionsFor(null)}
            title={`${L("Admin:Permissions")} · ${permissionsFor.name ?? ""}`}
          />
        </Suspense>
      )}
    </section>
  );
}

import type { Localize } from "@jcoder/abp-react/react";
import { z } from "zod";
import { postApiIdentityRolesBody, postApiIdentityRolesBodyNameMax } from "@/api/schemas/role/role";

// roles.tsx 的 name 校验规则单独落到这个 `-` 前缀文件（route 文件生成器按前缀跳过，不会被
// 误当路由）：roles.tsx 经 `@/auth`（含 @tanstack/react-start 的 server fn）链路，在没有
// tanstackStart vite 插件的 vitest 环境里无法被测试文件直接 import；测试需要挂真实产物而非
// 复刻校验规则，这份不依赖 `@/auth`/`createFileRoute` 的模块因此是两边（页面 + 测试）都能安全
// import 的唯一交点。

/** 以生成的 body schema 为基底：max(256) 这类后端约束免费继承（此前漏了，超长要打到后端才
 * 400）；必填与 trim 是 UI 语义、生成侧没有（ABP [Required] 未映射成 minLength），词条消息在
 * 此覆盖。 */
export function buildRoleSchema(L: Localize) {
  return postApiIdentityRolesBody.extend({
    name: z
      .string()
      .trim()
      .min(1, L("Form:Required"))
      .max(postApiIdentityRolesBodyNameMax, L("Form:MaxLength", postApiIdentityRolesBodyNameMax)),
  });
}

import { useLocalization } from "@jcoder/abp-react/react";
import { createFileRoute } from "@tanstack/react-router";
import { useMemo } from "react";
import { z } from "zod";
import {
  getGetApiMultiTenancyTenantsQueryKey,
  useDeleteApiMultiTenancyTenantsId,
  useGetApiMultiTenancyTenants,
  usePostApiMultiTenancyTenants,
  usePutApiMultiTenancyTenantsId,
} from "@/api/endpoints/tenant/tenant";
import type {
  VoloAbpTenantManagementTenantDto,
  VoloAbpTenantManagementTenantUpdateDto,
} from "@/api/models";
import {
  postApiMultiTenancyTenantsBody,
  postApiMultiTenancyTenantsBodyAdminEmailAddressMax,
  postApiMultiTenancyTenantsBodyAdminPasswordMax,
  postApiMultiTenancyTenantsBodyNameMax,
} from "@/api/schemas/tenant/tenant";
import { requirePermission } from "@/auth";
import { createCrudService } from "@/components/abp/crud/crud-service";
import { useAbpSheet } from "@/components/abp/sheet/use-abp-sheet";
import { useAbpTable } from "@/components/abp/table/use-abp-table";
import type { TableColumnDef } from "@/components/data-table/table-core";
import { TenantManagementPermissions } from "@/permissions";
import { RouteError } from "@/routes/shell-boundary";

/** /tenants：TenantManagement 模块的租户 CRUD；create/edit 字段集不同：create 额外收
 * adminEmailAddress/adminPassword（开租户时建种子管理员），edit 只改 name（后端 TenantUpdateDto
 * 本就不收管理员字段，修改管理员是另一条 Identity.Users 链路）。 */
export const Route = createFileRoute("/_layout/_authed/tenants/")({
  beforeLoad: requirePermission(TenantManagementPermissions.Tenants.Default),
  errorComponent: RouteError,
  component: TenantsPage,
});

const tenantService = createCrudService({
  useList: useGetApiMultiTenancyTenants,
  useCreate: usePostApiMultiTenancyTenants,
  useUpdate: usePutApiMultiTenancyTenantsId,
  useDelete: useDeleteApiMultiTenancyTenantsId,
  listKey: getGetApiMultiTenancyTenantsQueryKey,
  policy: TenantManagementPermissions.Tenants.Default,
});

interface TenantFormValues {
  name: string;
  adminEmailAddress: string;
  adminPassword: string;
}

const EMPTY_VALUES: TenantFormValues = { name: "", adminEmailAddress: "", adminPassword: "" };

// toValues 显式保留（不用默认的 pick-and-coalesce）：密码是业务上刻意的单向字段，
// 记录里从没有它，回填必须固定为空串，不能让默认实现的「按 emptyValues 键从记录 pick」
// 悄悄从别的同名字段带出值。
function toRecordValues(record: VoloAbpTenantManagementTenantDto): TenantFormValues {
  return { name: record.name ?? "", adminEmailAddress: "", adminPassword: "" };
}

// toUpdate 显式保留：update DTO 没有 admin 字段，若省略、退化到默认 identity 映射，会把
// adminEmailAddress/adminPassword 两个空串也塞进 PUT 请求体（依赖后端「忽略未知属性」的隐式
// 契约，而不是让接口形状本身说话）。这里没有触发类型层的条件必填：TenantUpdateDto 的必填
// 字段只有 name，TenantFormValues 结构上仍满足 `extends` 关系，toUpdate 类型层其实可省。
// 真正会被强制显式传的是「目标 DTO 存在 TValues 没有的必填字段」，见
// abp-sheet-contract.test-d.ts 的负例。
function toUpdateInput(value: TenantFormValues): VoloAbpTenantManagementTenantUpdateDto {
  return { name: value.name };
}

function TenantsPage() {
  const L = useLocalization();

  const columns = useMemo<TableColumnDef<VoloAbpTenantManagementTenantDto>[]>(
    () => [{ accessorKey: "name", header: () => L("AbpTenantManagement::TenantName") }],
    [L],
  );

  const sheet = useAbpSheet(tenantService, {
    emptyValues: EMPTY_VALUES,
    toValues: (record) => toRecordValues(record),
    toUpdate: toUpdateInput,
    // 以生成的 body schema 为基底：max64/max256/max128 这类后端约束免费继承；
    // adminEmailAddress/adminPassword 沿用既有 mode 分支（仅 create 收，edit 分支放行空串，
    // 因为 TenantUpdateDto 本就不带这两个字段），max 从生成常量取，消息在此覆盖。
    schema: (mode) => {
      const isCreate = mode === "create";
      return postApiMultiTenancyTenantsBody.extend({
        name: z
          .string()
          .trim()
          .min(1, L("Form:Required"))
          .max(
            postApiMultiTenancyTenantsBodyNameMax,
            L("Form:MaxLength", postApiMultiTenancyTenantsBodyNameMax),
          ),
        adminEmailAddress: isCreate
          ? z
              .string()
              .trim()
              .min(1, L("Form:Required"))
              .max(
                postApiMultiTenancyTenantsBodyAdminEmailAddressMax,
                L("Form:MaxLength", postApiMultiTenancyTenantsBodyAdminEmailAddressMax),
              )
              .pipe(z.email(L("Form:InvalidEmail")))
          : z.string(),
        adminPassword: isCreate
          ? z
              .string()
              .trim()
              .min(1, L("Form:Required"))
              .max(
                postApiMultiTenancyTenantsBodyAdminPasswordMax,
                L("Form:MaxLength", postApiMultiTenancyTenantsBodyAdminPasswordMax),
              )
          : z.string(),
      });
    },
  });

  const t = useAbpTable(tenantService, { columns, onOpen: sheet.open });
  const isCreate = sheet.mode === "create";

  return (
    <section className="space-y-4">
      <h1 className="text-2xl font-normal">{L("AbpTenantManagement::Tenants")}</h1>
      <t.Table>
        <t.BulkBar>
          <t.BulkDelete />
        </t.BulkBar>
      </t.Table>
      <sheet.Sheet>
        <sheet.form.AppForm>
          <sheet.form.FormErrors />
        </sheet.form.AppForm>

        <sheet.form.AppField name="name">
          {(field) => (
            <field.TextField
              label={L("AbpTenantManagement::TenantName")}
              required
